#![cfg_attr(rustfmt, rustfmt_skip)]
use super::*;

fn file(name: &str, bytes: &[u8]) -> std::path::PathBuf {
    let path = std::env::temp_dir().join(format!("og-import-{}-{name}", std::process::id())); std::fs::write(&path, bytes).unwrap(); path
}

fn import(path: &Path, mapping: JsonValue) -> (Vec<JsonValue>, JsonValue) {
    let mut out = Vec::new(); transform_stream(path, &mapping, &mut out).unwrap();
    let lines: Vec<JsonValue> = String::from_utf8(out).unwrap().lines().map(|line| serde_json::from_str(line).unwrap()).collect();
    let summary = lines.last().unwrap().clone();
    (lines.iter().filter_map(|line| line.get("documents")).flat_map(|documents| documents.as_array().unwrap().clone()).collect(), summary)
}

const WORKBOOK: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/fixtures/import/workbook.xlsx");

#[test] fn a_text_file_is_analyzed_and_imported_with_its_dates_numbers_and_computed_fields() { let path = file("sales.csv", "Export du 01/02/2025;;;;\n;;;;\nMois;Client;Montant;Date;Actif\n01-2025;C1;1 234,56;15/01/2025;oui\n02-2025;C2;(12,5);03/02/2025;non\n03-2025;C1;16,2%;28/02/2025;vrai\nTotal;;1 238,24;;\n".as_bytes()); let analysis = analyze(&path).unwrap(); let table = &analysis["tables"][0]; assert_eq!(table["titleRows"], json!(["Export du 01/02/2025"])); assert_eq!((table["headerRow"].clone(), table["columns"].clone(), table["rowCount"].clone(), table["footerRows"].clone()), (json!(3), json!(["Mois", "Client", "Montant", "Date", "Actif"]), json!(3), json!(["Total"]))); assert_eq!(table["profile"].as_array().unwrap().iter().map(|item| format!("{}/{}{}", item["type"].as_str().unwrap(), item["role"].as_str().unwrap(), item["format"].as_str().map(|format| format!("/{format}")).unwrap_or_default())).collect::<Vec<_>>(), ["month/time", "text/axis", "number/measure", "date/time/dmy", "boolean/attribute"]); assert_eq!(analysis["fingerprint"], scalar::sha1_hex(table["fingerprint"].as_str().unwrap().as_bytes())); let mapping = json!({"fields": [{"source": "Mois", "target": "date", "transform": "month"}, {"source": "Client", "target": "client"}, {"source": "Montant", "target": "amount", "transform": "number"}, {"source": "Date", "target": "day", "transform": "date", "format": "dmy"}, {"source": "Actif", "target": "active", "transform": "boolean"}, {"source": "Absent", "target": "x"}], "computed": [{"target": "source", "value": "export"}, {"target": "key", "type": "concat", "separator": "/", "fields": ["client", "day"]}, {"target": "net", "type": "formula", "terms": [{"source": "Montant"}, {"source": "Client", "sign": -1}, {"value": 10}]}]}); let (documents, summary) = import(&path, mapping); assert_eq!(documents[1], json!({"date": 1_738_368_000_000_i64, "client": "C2", "amount": -12.5, "day": "2025-02-03", "active": false, "source": "export", "key": "C2/2025-02-03", "net": -2.5})); assert_eq!((documents[2]["amount"].clone(), documents[0]["date"].clone()), (json!(0.162), json!(1_735_689_600_000_i64))); assert_eq!((summary["rowCount"].clone(), summary["warnings"][0].clone(), summary["warnings"][1].clone(), summary["warnings"].as_array().unwrap().last().unwrap().clone()), (json!(3), json!({"row": 1, "field": "Absent", "message": "source column missing"}), json!({"row": 1, "field": "Client", "message": "not a number: C1"}), json!({"row": 4, "message": "footer row left out: Total"}))); std::fs::remove_file(path).unwrap(); }

#[test] fn a_workbook_gives_its_typed_cells_and_its_tables() { let analysis = analyze(Path::new(WORKBOOK)).unwrap(); let tables: Vec<(String, JsonValue, JsonValue)> = analysis["tables"].as_array().unwrap().iter().map(|table| (table["name"].as_str().unwrap().to_owned(), table["headerRow"].clone(), table["rowCount"].clone())).collect(); assert_eq!(tables, [("Typé".into(), json!(3), json!(30)), ("Groupes".into(), json!(2), json!(2)), ("Deux tableaux".into(), json!(1), json!(3)), ("Deux tableaux (2)".into(), json!(7), json!(2)), ("Nommé".into(), json!(2), json!(2)), ("Vide".into(), json!(1), json!(0)), ("Caché".into(), json!(1), json!(1))]); assert_eq!(analysis["tables"][1]["columns"], json!(["Client", "2025 / CA", "2025 / Marge", "2026 / CA", "2026 / Marge"])); assert_eq!((analysis["tables"][0]["footerRows"].clone(), analysis["tables"][3]["footerRows"].clone(), analysis["tables"][6]["hidden"].clone()), (json!(["note seule"]), json!(["Total"]), json!(true))); assert_eq!(analysis["tables"][0]["preview"][0], json!({"Date": "2025-01-01T00:00:00", "Horodatage": "2025-01-01T08:30:01", "Heure": "09:01:00", "Entier": "10", "Décimal": "0.333333333333333", "Booléen": "false", "Texte": "Article 1", "Code": "1", "Mois": "2025-02-01T00:00:00", "Grand": "15000000000000000"})); let mapping = json!({"source": {"sheet": "Typé"}, "fields": [{"source": "Date", "target": "d", "transform": "date"}, {"source": "Horodatage", "target": "t", "transform": "datetime"}, {"source": "Horodatage", "target": "s"}, {"source": "Mois", "target": "m", "transform": "month"}, {"source": "Décimal", "target": "n", "transform": "number"}, {"source": "Booléen", "target": "b"}, {"source": "Entier", "target": "e", "transform": "other"}]}); let (documents, _) = import(Path::new(WORKBOOK), mapping); assert_eq!(documents[1], json!({"d": "2025-01-02", "t": "2025-01-02T08:30:02", "s": "2025-01-02 08:30:02", "m": 1_740_787_200_000_i64, "n": 2.0 / 3.0, "b": "True", "e": 20})); let (documents, _) = import(Path::new(WORKBOOK), json!({"source": {"sheet": "Deux tableaux (2)"}, "fields": [{"source": "Produit", "target": "p"}, {"source": "Prix", "target": "x", "transform": "number"}]})); assert_eq!(documents, [json!({"p": "A", "x": 1.5}), json!({"p": "B", "x": 2.5})]); }

#[test] fn a_request_runs_or_fails_as_a_json_error() { let path = file("one.csv", b"a;b\n1;2\n"); let mut out = Vec::new(); run(&json!({"operation": "preview", "file": path, "mapping": {"fields": [{"source": "a", "target": "a"}]}}).to_string(), &mut out).unwrap(); assert_eq!(serde_json::from_slice::<JsonValue>(&out).unwrap(), json!({"status": "transformed", "documents": [{"a": "1"}], "rowCount": 1, "warnings": []})); assert_eq!(run(&json!({"operation": "explode", "file": path}).to_string(), &mut Vec::new()), Err("unsupported operation: explode".into())); assert!(analyze(Path::new("/nonexistent/file.csv")).unwrap_err().starts_with("cannot read the file")); std::fs::remove_file(path).unwrap(); }

// A mapping naming no sheet of the file takes the table holding most of its source columns.
#[test] fn a_mapping_without_its_sheet_takes_the_table_holding_its_columns() { let (documents, _) = import(Path::new(WORKBOOK), json!({"source": {"sheet": "Ancien nom"}, "fields": [{"source": "Produit", "target": "p"}, {"source": "Prix", "target": "x", "transform": "number"}]})); assert_eq!(documents, [json!({"p": "A", "x": 1.5}), json!({"p": "B", "x": 2.5})]); let (documents, _) = import(Path::new(WORKBOOK), json!({"fields": [{"source": "Nom", "target": "n"}]})); assert_eq!(documents, [json!({"n": "x"}), json!({"n": "y"})]); }
